	name := filepath.Join(t.TempDir(), "config.json")
	if err := os.WriteFile(name, body, 0o600); err != nil { t.Fatal(err) }
	if _, err := loadConfig(name); err == nil { t.Fatal("unknown configuration field accepted") }
}

func TestCredentialFileRequiresExact0600AndContent(t *testing.T) {
	name := filepath.Join(t.TempDir(), "token")
	if err := os.WriteFile(name, []byte("secret\n"), 0o600); err != nil { t.Fatal(err) }
