const PolicyVersion = "1.0"

var (
	commitPattern = regexp.MustCompile(`^[0-9a-f]{40}$`)
	imagePattern  = regexp.MustCompile(`^sha256:[0-9a-f]{64}$`)
)

type Repository struct {
	Owner      string `json:"owner"`
	Name       string `json:"name"`
	Root       string `json:"root"`
	Remote     string `json:"remote"`
	RemoteURL  string `json:"remote_url"`
	BaseBranch string `json:"base_branch"`
	BaseCommit string `json:"base_commit"`
}

type Paths struct {
	Readable   []string `json:"readable"`
	Writable   []string `json:"writable"`
	Prohibited []string `json:"prohibited"`
}

type Limits struct {
	MaximumTasks            int   `json:"maximum_tasks"`
	MaximumChangedFiles     int   `json:"maximum_changed_files"`
	MaximumFileBytes        int64 `json:"maximum_file_bytes"`
	MaximumTotalBytes       int64 `json:"maximum_total_bytes"`
	ExecutionConcurrency    int   `json:"execution_concurrency"`
	VerificationConcurrency int   `json:"verification_concurrency"`
}

type Images struct {
	Execution    string `json:"execution"`
	Verification string `json:"verification"`
}

type Policy struct {
	Version       string     `json:"version"`
	Repository    Repository `json:"repository"`
	Paths         Paths      `json:"paths"`
	TrustedChecks []string   `json:"trusted_checks"`
	Limits        Limits     `json:"limits"`
	Images        Images     `json:"images"`
}

func DecodePolicy(body []byte) (Policy, error) {
	decoder := json.NewDecoder(bytes.NewReader(body))
	decoder.DisallowUnknownFields()
	var value Policy
	if err := decoder.Decode(&value); err != nil {
		return Policy{}, err
	}
	var trailing any
	if err := decoder.Decode(&trailing); !errors.Is(err, io.EOF) {
		return Policy{}, errors.New("policy has trailing content")
	}
	if err := value.Validate(); err != nil {
		return Policy{}, err
	}
	return value, nil
}

func (p Policy) Canonical() ([]byte, string, error) {
	if err := p.Validate(); err != nil {
		return nil, "", err
	}
	body, err := json.Marshal(p)
	if err != nil {
		return nil, "", err
	}
	digest := sha256.Sum256(body)
	return body, hex.EncodeToString(digest[:]), nil
}

func (p Policy) Validate() error {
	if p.Version != PolicyVersion {
		return errors.New("unsupported beta policy version")
	}
	r := p.Repository
	if r.Owner == "" || r.Name == "" || r.Remote == "" || r.RemoteURL == "" ||
		r.BaseBranch == "" || !cleanAbsolute(r.Root) || !commitPattern.MatchString(r.BaseCommit) {
		return errors.New("invalid repository policy")
	}
	if !imagePattern.MatchString(p.Images.Execution) || !imagePattern.MatchString(p.Images.Verification) {
		return errors.New("worker images must be immutable sha256 identities")
	}
	if p.Limits.MaximumTasks != 1 || p.Limits.MaximumChangedFiles < 1 ||
		p.Limits.MaximumFileBytes < 1 || p.Limits.MaximumTotalBytes < p.Limits.MaximumFileBytes ||
		p.Limits.ExecutionConcurrency < 1 || p.Limits.VerificationConcurrency < 1 ||
		p.Limits.MaximumChangedFiles > 100 || p.Limits.MaximumFileBytes > 1<<20 ||
		p.Limits.MaximumTotalBytes > 10<<20 || p.Limits.ExecutionConcurrency > 4 ||
		p.Limits.VerificationConcurrency > 2 {
		return errors.New("invalid beta limits")
	}
	if err := validatePathPolicy(p.Paths); err != nil {
		return err
	}
	if len(p.TrustedChecks) == 0 {
		return errors.New("trusted checks are required")
	}
	seen := map[string]bool{}
	for _, check := range p.TrustedChecks {
		if check == "" || strings.TrimSpace(check) != check || seen[check] {
			return errors.New("trusted checks must be unique and non-empty")
		}
		seen[check] = true
	}
	if !slices.IsSorted(p.TrustedChecks) {
		return errors.New("trusted checks must be sorted")
	}
	return nil
}

func validatePathPolicy(value Paths) error {
	for _, group := range [][]string{value.Readable, value.Writable, value.Prohibited} {
		if len(group) == 0 || !slices.IsSorted(group) {
			return errors.New("policy paths must be non-empty and sorted")
		}
		previous := ""
		for _, item := range group {
			if !safePath(item) || item == previous {
				return errors.New("invalid or duplicate policy path")
			}
			previous = item
		}
	}
	for _, writable := range value.Writable {
		if !WithinAny(writable, value.Readable) || WithinAny(writable, value.Prohibited) {
			return errors.New("writable paths must be readable and not prohibited")
		}
	}
	for _, prohibited := range value.Prohibited {
		if WithinAny(prohibited, value.Writable) {
			return errors.New("prohibited and writable paths overlap")
		}
	}
	return nil
}

func safePath(value string) bool {
	return value != "" && value != "." && !strings.HasPrefix(value, "/") &&
		path.Clean(value) == value && !strings.HasPrefix(value, "../") && !strings.ContainsRune(value, '\x00')
}

func WithinAny(value string, roots []string) bool {
	for _, root := range roots {
		if value == root || strings.HasPrefix(value, root+"/") {
			return true
		}
	}
	return false
}

func cleanAbsolute(value string) bool { return filepath.IsAbs(value) && filepath.Clean(value) == value }

// VerifyRemoteBase rechecks the configured remote and approved branch without changing refs.
func VerifyRemoteBase(ctx context.Context, p Policy) error {
	if err := p.Validate(); err != nil {
		return err
	}
	configured, err := git(ctx, p.Repository.Root, "remote", "get-url", p.Repository.Remote)
	if err != nil || configured != p.Repository.RemoteURL {
		return errors.New("repository remote mismatch")
	}
	head, err := git(ctx, p.Repository.Root, "ls-remote", "--heads", p.Repository.Remote, "refs/heads/"+p.Repository.BaseBranch)
	if err != nil {
		return fmt.Errorf("read remote base: %w", err)
	}
	fields := strings.Fields(head)
	if len(fields) != 2 || fields[0] != p.Repository.BaseCommit {
		return errors.New("approved remote base moved")
	}
	resolved, err := git(ctx, p.Repository.Root, "rev-parse", "--verify", p.Repository.BaseCommit+"^{commit}")
	if err != nil || resolved != p.Repository.BaseCommit {
		return errors.New("approved base is not a local commit")
	}
	localHead, err := git(ctx, p.Repository.Root, "rev-parse", "--verify", "refs/heads/"+p.Repository.BaseBranch)
	if err != nil || localHead != p.Repository.BaseCommit {
		return errors.New("local base branch does not equal approved commit")
	}
	return nil
}

func git(ctx context.Context, root string, args ...string) (string, error) {
	command := exec.CommandContext(ctx, "git", append([]string{"-C", root}, args...)...)
	command.Env = append(command.Environ(), "GIT_TERMINAL_PROMPT=0")
	output, err := command.CombinedOutput()
	if err != nil {
		return "", fmt.Errorf("git %s: %w", args[0], err)
	}
	return strings.TrimSpace(string(output)), nil
}
// Package migration applies embedded, forward-only PostgreSQL migrations.
package migration

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io/fs"
	"path"
	"slices"
	"sort"
	"strconv"
	"strings"

	"github.com/jackc/pgx/v5"
)

type Source struct {
	Files     fs.FS
	Directory string
}

type Expected struct {
	Version      int64
	Name, Digest string
}

func Describe(sources ...Source) ([]Expected, error) {
	var result []Expected
	seen := map[int64]bool{}
	for _, source := range sources {
		items, err := readAll(source.Files, source.Directory)
		if err != nil {
			return nil, err
		}
		for _, value := range items {
			if seen[value.version] {
				return nil, fmt.Errorf("duplicate migration version %d", value.version)
			}
			seen[value.version] = true
			result = append(result, Expected{Version: value.version, Name: value.name, Digest: value.digest})
		}
	}
	slices.SortFunc(result, func(a, b Expected) int { return int(a.Version - b.Version) })
	return result, nil
}

// Verify checks the existing ledger without applying migrations or creating schema objects.
func Verify(ctx context.Context, connectionString string, sources ...Source) ([]Expected, error) {
	expected, err := Describe(sources...)
	if err != nil {
		return nil, err
	}
	config, err := pgx.ParseConfig(connectionString)
	if err != nil {
		return nil, fmt.Errorf("parse migration connection: %w", err)
	}
	if config.RuntimeParams == nil {
		config.RuntimeParams = map[string]string{}
	}
	config.RuntimeParams["default_transaction_read_only"] = "on"
	connection, err := pgx.ConnectConfig(ctx, config)
	if err != nil {
		return nil, fmt.Errorf("connect for migration verification: %w", err)
	}
	defer func() { _ = connection.Close(ctx) }()
	var ledger *string
	if err := connection.QueryRow(ctx, `SELECT to_regclass('schema_migrations')::text`).Scan(&ledger); err != nil || ledger == nil {
		return nil, errors.New("migration ledger missing")
	}
	rows, err := connection.Query(ctx, `SELECT version,name,digest FROM schema_migrations ORDER BY version`)
	if err != nil {
		return nil, fmt.Errorf("read migration ledger: %w", err)
	}
	defer rows.Close()
	actual := map[int64]Expected{}
	for rows.Next() {
		var item Expected
		if err := rows.Scan(&item.Version, &item.Name, &item.Digest); err != nil {
			return nil, err
		}
		actual[item.Version] = item
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	for _, item := range expected {
		stored, ok := actual[item.Version]
		if !ok {
			return nil, fmt.Errorf("migration %d pending", item.Version)
		}
		if stored.Name != item.Name {
			return nil, fmt.Errorf("migration %d name changed", item.Version)
		}
		if stored.Digest != item.Digest {
			return nil, fmt.Errorf("migration %d digest changed", item.Version)
		}
	}
	expectedVersions := make(map[int64]bool, len(expected))
	for _, item := range expected {
		expectedVersions[item.Version] = true
	}
	for version := range actual {
		if !expectedVersions[version] {
			return nil, fmt.Errorf("unexpected migration %d", version)
		}
	}
	return expected, nil
}

const advisoryLock int64 = 719043625421948938

// Apply serializes and applies the SQL files in directory, recording their
// content digests in the shared schema_migrations ledger.
func Apply(ctx context.Context, connectionString string, files fs.FS, directory string) error {
	connection, err := pgx.Connect(ctx, connectionString)
	if err != nil {
		return fmt.Errorf("connect for migrations: %w", err)
	}
	defer func() { _ = connection.Close(ctx) }()

	if _, err := connection.Exec(ctx, `SELECT pg_advisory_lock($1)`, advisoryLock); err != nil {
		return fmt.Errorf("lock migrations: %w", err)
	}
	defer func() {
		_, _ = connection.Exec(context.Background(), `SELECT pg_advisory_unlock($1)`, advisoryLock)
	}()

	if _, err := connection.Exec(ctx, `CREATE TABLE IF NOT EXISTS schema_migrations (
		version bigint PRIMARY KEY,
		name text NOT NULL,
		digest text NOT NULL CHECK (digest ~ '^[a-f0-9]{64}$'),
		applied_at timestamptz NOT NULL DEFAULT now()
	)`); err != nil {
		return fmt.Errorf("create migration ledger: %w", err)
	}

	migrations, err := readAll(files, directory)
	if err != nil {
		return err
	}
	for _, item := range migrations {
		if err := applyOne(ctx, connection, item); err != nil {
			return err
		}
	}
	return nil
}

type item struct {
	version int64
	name    string
	digest  string
	body    []byte
}

func readAll(files fs.FS, directory string) ([]item, error) {
	entries, err := fs.ReadDir(files, directory)
	if err != nil {
		return nil, fmt.Errorf("read migrations: %w", err)
	}
	result := make([]item, 0, len(entries))
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".sql") {
			continue
		}
		value, err := read(files, directory, entry.Name())
		if err != nil {
			return nil, err
		}
		result = append(result, value)
	}
	sort.Slice(result, func(i, j int) bool { return result[i].version < result[j].version })
	for index := 1; index < len(result); index++ {
		if result[index-1].version == result[index].version {
			return nil, fmt.Errorf(
				"duplicate migration version %d in %q and %q",
				result[index].version, result[index-1].name, result[index].name,
			)
		}
	}
	return result, nil
}

func read(files fs.FS, directory, name string) (item, error) {
	versionText, _, ok := strings.Cut(name, "_")
	if !ok {
		return item{}, fmt.Errorf("invalid migration filename %q", name)
	}
	version, err := strconv.ParseInt(versionText, 10, 64)
	if err != nil {
		return item{}, fmt.Errorf("invalid migration version %q: %w", name, err)
	}
	body, err := fs.ReadFile(files, path.Join(directory, name))
	if err != nil {
		return item{}, fmt.Errorf("read migration %q: %w", name, err)
	}
	sum := sha256.Sum256(body)
	return item{
		version: version, name: name, body: body,
		digest: hex.EncodeToString(sum[:]),
	}, nil
}

func applyOne(ctx context.Context, connection *pgx.Conn, value item) error {
	var stored string
	err := connection.QueryRow(ctx,
		`SELECT digest FROM schema_migrations WHERE version=$1`, value.version,
	).Scan(&stored)
	if err == nil {
		if stored != value.digest {
			return fmt.Errorf("migration %d digest changed", value.version)
		}
		return nil
	}
	if err != pgx.ErrNoRows {
		return fmt.Errorf("read migration %d: %w", value.version, err)
	}
	tx, err := connection.Begin(ctx)
	if err != nil {
		return fmt.Errorf("begin migration %d: %w", value.version, err)
	}
	defer func() { _ = tx.Rollback(ctx) }()
	if _, err := tx.Exec(ctx, string(value.body)); err != nil {
		return fmt.Errorf("apply migration %d: %w", value.version, err)
	}
	if _, err := tx.Exec(ctx,
		`INSERT INTO schema_migrations(version,name,digest) VALUES($1,$2,$3)`,
		value.version, value.name, value.digest); err != nil {
		return fmt.Errorf("record migration %d: %w", value.version, err)
	}
	if err := tx.Commit(ctx); err != nil {
		return fmt.Errorf("commit migration %d: %w", value.version, err)
	}
	return nil
}
